require_once 'includes/auth.php';require_once 'includes/db.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$st=db()->prepare('SELECT p.*,e.nome equipe_nome,e.sigla FROM patinadores p LEFT JOIN equipes e ON e.id=p.equipe_id WHERE p.id=?');$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Atleta não encontrado.');}$r=db()->prepare('SELECT r.*,c.nome campeonato FROM resultados r JOIN campeonatos c ON c.id=r.campeonato_id WHERE r.patinador_id=? AND r.confirmado=1 ORDER BY c.data_inicio DESC');$r->execute([$id]);$results=$r->fetchAll();$pageTitle=$p['nome'];require 'includes/header.php'; ?>
<a class="back-link" href="patinadores.php">← Voltar aos patinadores</a><section class="profile-hero"><img src="<?= e($p['foto']) ?>" alt="Foto ilustrativa de <?= e($p['nome']) ?>"><div class="profile-copy"><span class="eyebrow">ATHLETE PROFILE · <?= e($p['sigla']??'ISU') ?></span><h1><?= e($p['nome']) ?></h1><p><?= e($p['pais']) ?> · <?= e($p['disciplina']) ?></p><div class="profile-tags"><span><?= e($p['equipe_nome']??'Equipe não informada') ?></span><?php if($p['idade']): ?><span><?= (int)$p['idade'] ?> anos</span><?php endif; ?></div></div></section><section class="profile-columns"><div class="panel"><span class="eyebrow">ABOUT THE ATHLETE</span><h2>Trajetória</h2><p><?= nl2br(e($p['biografia']??'Informações ainda não cadastradas.')) ?></p><h3>Conquistas</h3><p><?= nl2br(e($p['conquistas']??'Não informado.')) ?></p><h3>Treinador(a)</h3><p><?= e($p['treinador']??'Não informado') ?></p></div><div class="panel"><span class="eyebrow">COMPETITION HISTORY</span><h2>Resultados confirmados</h2><?php if(!$results): ?><p class="muted">Ainda não há resultados publicados para este atleta.</p><?php else: foreach($results as $res): ?><div class="history-row"><b><?= e($res['campeonato']) ?></b><span><?= number_format((float)$res['total_final'],2,'.','') ?> pts</span></div><?php endforeach; endif; ?></div></section>
